/**
 * The tape: what rec stores, and how it travels inside a URL.
 *
 * A tape keeps only what can't be rebuilt on replay — the text of each delta
 * and the gap before it. The OpenAI SSE envelope is regenerated by the replay
 * function, which keeps the URL small.
 *
 * Zero dependencies: CompressionStream, TextEncoder, btoa/atob and
 * crypto.subtle are built into modern browsers, Node 18+ and edge runtimes, so
 * this one file runs unchanged in the gateway page and the replay function.
 *
 * Canonical copy. The portfolio gateway (abhirupa-digital-garden,
 * lib/rec/tape.ts) carries an identical copy — change both together.
 */

export type Tape = {
  v: 1;
  /** Model name, echoed back in replay. */
  m: string;
  /** Milliseconds from request start to the first chunk (ttfb). */
  f: number;
  /** [gap ms, delta text] pairs; gaps rounded to 1 ms. */
  c: [number, string][];
};

/** Hosts cap URL length; 8 kB of encoded tape is the planned safe ceiling. */
export const MAX_ENCODED_BYTES = 8000;

/** Inflate guard for the replay function: a tape never needs more than this. */
const MAX_DECODED_BYTES = 1_000_000;

export class TapeError extends Error {
  override name = 'TapeError';
}

// ---------------------------------------------------------------------------
// Validation
// ---------------------------------------------------------------------------

export function isTape(value: unknown): value is Tape {
  if (!value || typeof value !== 'object') return false;
  const t = value as Record<string, unknown>;
  return (
    t.v === 1 &&
    typeof t.m === 'string' &&
    typeof t.f === 'number' &&
    Number.isFinite(t.f) &&
    t.f >= 0 &&
    Array.isArray(t.c) &&
    t.c.every(
      (pair) =>
        Array.isArray(pair) &&
        pair.length === 2 &&
        typeof pair[0] === 'number' &&
        Number.isFinite(pair[0]) &&
        pair[0] >= 0 &&
        typeof pair[1] === 'string',
    )
  );
}

/** Total playback time at speed 1: ttfb plus every gap. */
export function tapeDurationMs(tape: Tape): number {
  return tape.c.reduce((sum, [gap]) => sum + gap, tape.f);
}

// ---------------------------------------------------------------------------
// Codec: Tape <-> URL segment
// JSON.stringify -> deflate-raw -> base64url, and back.
// ---------------------------------------------------------------------------

export async function encodeTape(tape: Tape): Promise<string> {
  const json = new TextEncoder().encode(JSON.stringify(tape));
  const deflated = await pipeThrough(json, new CompressionStream('deflate-raw'));
  return toBase64Url(deflated);
}

export async function decodeTape(segment: string): Promise<Tape> {
  if (!segment || segment.length > MAX_ENCODED_BYTES) {
    throw new TapeError(
      segment ? `Tape is ${segment.length} bytes; the cap is ${MAX_ENCODED_BYTES}.` : 'Tape is empty.',
    );
  }

  let bytes: Uint8Array<ArrayBuffer>;
  try {
    bytes = fromBase64Url(segment);
  } catch {
    throw new TapeError('Tape is not valid base64url.');
  }

  let json: string;
  try {
    const inflated = await pipeThrough(bytes, new DecompressionStream('deflate-raw'), MAX_DECODED_BYTES);
    json = new TextDecoder().decode(inflated);
  } catch {
    throw new TapeError('Tape could not be inflated.');
  }

  let value: unknown;
  try {
    value = JSON.parse(json);
  } catch {
    throw new TapeError('Tape is not valid JSON.');
  }
  if (!isTape(value)) throw new TapeError('Tape does not match format v1.');
  return value;
}

/** Content address: first 12 hex chars of sha256(encoded tape). */
export async function tapeId(encoded: string): Promise<string> {
  const digest = await crypto.subtle.digest('SHA-256', new TextEncoder().encode(encoded));
  return Array.from(new Uint8Array(digest).slice(0, 6), (b) => b.toString(16).padStart(2, '0')).join('');
}

async function pipeThrough(
  input: Uint8Array<ArrayBuffer>,
  transform: CompressionStream | DecompressionStream,
  maxOutput = Infinity,
): Promise<Uint8Array<ArrayBuffer>> {
  // Write without awaiting: awaiting before reading deadlocks on backpressure.
  const writer = transform.writable.getWriter();
  writer.write(input).catch(() => {});
  writer.close().catch(() => {});

  const reader = transform.readable.getReader();
  const parts: Uint8Array[] = [];
  let total = 0;
  for (;;) {
    const { done, value } = await reader.read();
    if (done) break;
    total += value.byteLength;
    if (total > maxOutput) {
      await reader.cancel();
      throw new TapeError('Tape inflates past the size limit.');
    }
    parts.push(value);
  }

  const out = new Uint8Array(total);
  let offset = 0;
  for (const part of parts) {
    out.set(part, offset);
    offset += part.byteLength;
  }
  return out;
}

function toBase64Url(bytes: Uint8Array): string {
  let binary = '';
  for (let i = 0; i < bytes.length; i++) binary += String.fromCharCode(bytes[i]);
  return btoa(binary).replace(/\+/g, '-').replace(/\//g, '_').replace(/=+$/, '');
}

function fromBase64Url(segment: string): Uint8Array<ArrayBuffer> {
  if (!/^[A-Za-z0-9_-]+$/.test(segment)) throw new TapeError('bad alphabet');
  const base64 = segment.replace(/-/g, '+').replace(/_/g, '/');
  const binary = atob(base64 + '='.repeat((4 - (base64.length % 4)) % 4));
  const bytes = new Uint8Array(binary.length);
  for (let i = 0; i < binary.length; i++) bytes[i] = binary.charCodeAt(i);
  return bytes;
}
